import test from 'node:test';
import assert from 'node:assert/strict';
import {createDecoder} from '../stream-framer.js';

const wire = 'event: delta\r\ndata: 雪😀\r\ndata: second\n\ndata: [DONE]\n\n';
const expected = [{event: 'delta', data: '雪😀\nsecond'}];

function runChunks(chunks) {
  const decoder = createDecoder();
  const frames = [];
  for (const chunk of chunks) frames.push(...decoder.push(chunk));
  assert.deepEqual(decoder.finish(), []);
  return frames;
}

test('decoding is invariant across every two-part split and bytewise transport', () => {
  const bytes = Buffer.from(wire);
  assert.deepEqual(runChunks([bytes]), expected);
  for (let split = 0; split <= bytes.length; split++) {
    assert.deepEqual(runChunks([bytes.subarray(0, split), bytes.subarray(split)]), expected);
  }
  assert.deepEqual(runChunks([...bytes].map((byte) => Uint8Array.of(byte))), expected);
});

test('field parsing preserves values and resets all frame state', () => {
  const decoder = createDecoder();
  const input = [
    'event: stale', '',
    ': ignored', 'unknown: value', 'Data: wrong', 'event: first', 'event: final:name',
    'data:  one space remains', 'data:two:colons', '',
    'event:', 'data', '',
    'data: a\rb', '',
    'data: [DONE]', '', '',
  ].join('\n');
  assert.deepEqual(decoder.push(Buffer.from(input)), [
    {event: 'final:name', data: ' one space remains\ntwo:colons'},
    {event: 'message', data: ''},
    {event: 'message', data: 'a\rb'},
  ]);
  assert.deepEqual(decoder.finish(), []);
});

test('only one initial BOM is ignored and later BOMs are data', () => {
  const input = '\uFEFFdata: first\n\ndata: \uFEFFlater\n\ndata: [DONE]\n\n';
  assert.deepEqual(runChunks([...Buffer.from(input)].map((byte) => Uint8Array.of(byte))), [
    {event: 'message', data: 'first'},
    {event: 'message', data: '\uFEFFlater'},
  ]);
});

test('chunks must be Uint8Arrays and are not mutated', () => {
  const decoder = createDecoder();
  const chunk = Buffer.from('data: [DONE]\n\n');
  const copy = Buffer.from(chunk);
  assert.deepEqual(decoder.push(chunk), []);
  assert.deepEqual(chunk, copy);
  assert.deepEqual(decoder.finish(), []);

  for (const bad of ['bytes', null, {}, [1, 2]]) {
    const invalid = createDecoder();
    assert.throws(() => invalid.push(bad), Error);
    assert.throws(() => invalid.push(new Uint8Array()), Error);
    assert.throws(() => invalid.finish(), Error);
  }
});

test('strict UTF-8 rejects malformed and incomplete sequences and poisons only that decoder', () => {
  const malformed = createDecoder();
  assert.throws(() => malformed.push(Uint8Array.of(0xc3, 0x28)), Error);
  assert.throws(() => malformed.push(Buffer.from('data: [DONE]\n\n')), Error);
  assert.throws(() => malformed.finish(), Error);

  const incomplete = createDecoder();
  assert.deepEqual(incomplete.push(Uint8Array.of(0xf0, 0x9f, 0x98)), []);
  assert.throws(() => incomplete.finish(), Error);
  assert.throws(() => incomplete.finish(), Error);

  const independent = createDecoder();
  assert.deepEqual(independent.push(Buffer.from('data: ok\n\ndata: [DONE]\n\n')), [
    {event: 'message', data: 'ok'},
  ]);
  assert.deepEqual(independent.finish(), []);
});

test('termination and completion enforce exact lifecycle rules', () => {
  for (const suffix of [': comment\n', 'unknown\n', 'data: [DONE]\n\n', 'x\n']) {
    const decoder = createDecoder();
    assert.throws(() => decoder.push(Buffer.from(`data: kept\n\ndata: [DONE]\n\n${suffix}`)), Error);
    assert.throws(() => decoder.finish(), Error);
  }

  const blanks = createDecoder();
  assert.deepEqual(blanks.push(Buffer.from('data: [DONE]\n\n\n\r\n')), []);
  assert.deepEqual(blanks.finish(), []);
  assert.throws(() => blanks.push(new Uint8Array()), Error);
  assert.throws(() => blanks.finish(), Error);

  for (const text of [
    '',
    'data: pending\n',
    'event: pending\n',
    'data: [DONE]\n',
    'data: [DONE]\n\ntail',
  ]) {
    const decoder = createDecoder();
    decoder.push(Buffer.from(text));
    assert.throws(() => decoder.finish(), Error);
    assert.throws(() => decoder.push(new Uint8Array()), Error);
  }
});

test('a failing push returns no partial result and earlier returned values remain stable', () => {
  const decoder = createDecoder();
  const first = decoder.push(Buffer.from('data: safe\n\n'));
  assert.deepEqual(first, [{event: 'message', data: 'safe'}]);
  assert.throws(() => decoder.push(Buffer.from('data: [DONE]\n\nforbidden\n')), Error);
  assert.deepEqual(first, [{event: 'message', data: 'safe'}]);
  assert.throws(() => decoder.finish(), Error);
});

