import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';

const script = fileURLToPath(new URL('../stream-framer.js', import.meta.url));

function invoke(args) {
  return spawnSync(process.execPath, [script, ...args], {encoding: 'utf8'});
}

function assertFailure(result) {
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.notEqual(result.stderr, '');
}

test('CLI emits one atomic JSON result for canonical base64 chunks', (t) => {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'stream-framer-'));
  t.after(() => fs.rmSync(directory, {recursive: true, force: true}));
  const file = path.join(directory, 'input.json');
  const bytes = Buffer.from('event: update\ndata: 雪\n\ndata: [DONE]\n\n');
  const chunks = [Buffer.alloc(0), ...[...bytes].map((byte) => Uint8Array.of(byte))]
    .map((chunk) => Buffer.from(chunk).toString('base64'));
  fs.writeFileSync(file, JSON.stringify({chunks, ignored: true}));

  const result = invoke([file]);
  assert.equal(result.status, 0);
  assert.equal(result.stderr, '');
  assert.equal(result.stdout, `${JSON.stringify({frames: [{event: 'update', data: '雪'}]})}\n`);
});

test('CLI validates argument count, files, UTF-8 JSON and input shape', (t) => {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'stream-framer-'));
  t.after(() => fs.rmSync(directory, {recursive: true, force: true}));
  assertFailure(invoke([]));
  assertFailure(invoke(['one', 'two']));
  assertFailure(invoke([path.join(directory, 'missing')]));

  const cases = [
    Buffer.from('{'),
    Buffer.from([0xff]),
    Buffer.from('null'),
    Buffer.from('[]'),
    Buffer.from('{}'),
    Buffer.from('{"chunks":null}'),
    Buffer.from('{"chunks":[7]}'),
  ];
  cases.forEach((contents, index) => {
    const file = path.join(directory, `bad-${index}`);
    fs.writeFileSync(file, contents);
    assertFailure(invoke([file]));
  });
});

test('CLI rejects malformed or noncanonical base64 and protocol failures', (t) => {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'stream-framer-'));
  t.after(() => fs.rmSync(directory, {recursive: true, force: true}));
  const invalid = ['Zg', 'Zg=', 'Zg===', 'Zh==', 'Zm9=', ' Zg==', 'Zg==\n', '-w==', '_w==', '!!!!'];
  for (const [index, encoded] of invalid.entries()) {
    const file = path.join(directory, `base64-${index}.json`);
    fs.writeFileSync(file, JSON.stringify({chunks: [encoded]}));
    assertFailure(invoke([file]));
  }

  for (const [index, bytes] of [Buffer.from('data: no terminator\n\n'), Buffer.from([0xff])].entries()) {
    const file = path.join(directory, `protocol-${index}.json`);
    fs.writeFileSync(file, JSON.stringify({chunks: [bytes.toString('base64')]}));
    assertFailure(invoke([file]));
  }
});

test('importing the module does not execute the CLI', () => {
  const source = `import ${JSON.stringify(new URL('../stream-framer.js', import.meta.url).href)};`;
  const result = spawnSync(process.execPath, ['--input-type=module', '--eval', source], {encoding: 'utf8'});
  assert.equal(result.status, 0);
  assert.equal(result.stdout, '');
  assert.equal(result.stderr, '');
});

