import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

export function createDecoder() {
  const utf8 = new TextDecoder('utf-8', {fatal: true});
  let lineBuffer = '';
  let dataValues = [];
  let eventSeen = false;
  let eventValue = '';
  let terminated = false;
  let finished = false;
  let poisoned = false;

  function reject(message, cause) {
    poisoned = true;
    throw new Error(message, cause === undefined ? undefined : {cause});
  }

  function ensureActive() {
    if (poisoned) reject('decoder is poisoned');
    if (finished) reject('decoder is already finished');
  }

  function resetFrame() {
    dataValues = [];
    eventSeen = false;
    eventValue = '';
  }

  function consumeLine(line, frames) {
    if (terminated) {
      if (line !== '') throw new Error('nonblank line after termination');
      return;
    }

    if (line === '') {
      if (dataValues.length > 0) {
        const data = dataValues.join('\n');
        if (data === '[DONE]') {
          terminated = true;
        } else {
          frames.push({
            event: !eventSeen || eventValue === '' ? 'message' : eventValue,
            data,
          });
        }
      }
      resetFrame();
      return;
    }

    if (line.startsWith(':')) return;
    const colon = line.indexOf(':');
    const field = colon === -1 ? line : line.slice(0, colon);
    let value = colon === -1 ? '' : line.slice(colon + 1);
    if (value.startsWith(' ')) value = value.slice(1);

    if (field === 'data') {
      dataValues.push(value);
    } else if (field === 'event') {
      eventSeen = true;
      eventValue = value;
    }
  }

  function consumeText(text, frames) {
    lineBuffer += text;
    let newline;
    while ((newline = lineBuffer.indexOf('\n')) !== -1) {
      let line = lineBuffer.slice(0, newline);
      lineBuffer = lineBuffer.slice(newline + 1);
      if (line.endsWith('\r')) line = line.slice(0, -1);
      consumeLine(line, frames);
    }
  }

  return {
    push(chunk) {
      ensureActive();
      if (!(chunk instanceof Uint8Array)) reject('chunk must be a Uint8Array');
      const frames = [];
      try {
        consumeText(utf8.decode(chunk, {stream: true}), frames);
        return frames;
      } catch (error) {
        poisoned = true;
        throw error instanceof Error ? error : new Error(String(error));
      }
    },

    finish() {
      ensureActive();
      try {
        const frames = [];
        consumeText(utf8.decode(), frames);
        if (lineBuffer !== '') throw new Error('unterminated final line');
        if (dataValues.length > 0 || eventSeen) throw new Error('pending frame fields');
        if (!terminated) throw new Error('stream is not terminated');
        if (frames.length > 0) throw new Error('frame completed during finish');
        finished = true;
        return [];
      } catch (error) {
        poisoned = true;
        throw error instanceof Error ? error : new Error(String(error));
      }
    },
  };
}

function decodeCanonicalBase64(value) {
  if (typeof value !== 'string') throw new Error('chunk encodings must be strings');
  if (!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(value)) {
    throw new Error('invalid base64');
  }
  const bytes = Buffer.from(value, 'base64');
  if (bytes.toString('base64') !== value) throw new Error('noncanonical base64');
  return bytes;
}

function runCli() {
  if (process.argv.length !== 3) throw new Error('usage: stream-framer.js INPUT_JSON_FILE');
  const fileBytes = fs.readFileSync(process.argv[2]);
  const jsonText = new TextDecoder('utf-8', {fatal: true}).decode(fileBytes);
  const input = JSON.parse(jsonText);
  if (input === null || typeof input !== 'object' || Array.isArray(input)) {
    throw new Error('input must be an object');
  }
  if (!Array.isArray(input.chunks)) throw new Error('chunks must be an array');

  const decoder = createDecoder();
  const frames = [];
  for (const encoded of input.chunks) frames.push(...decoder.push(decodeCanonicalBase64(encoded)));
  frames.push(...decoder.finish());
  process.stdout.write(`${JSON.stringify({frames})}\n`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    runCli();
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}

